// Reference ranges are representative adult values in conventional US units (SI where
// helpful). They vary by laboratory, method, age, and sex; the reporting laboratory's
// range always takes precedence. AI-drafted content pending expert review.

import type { ContentMeta, Investigation } from "../shared/types";

const DATE = "2026-10-25";

function meta(id: string, sources: string[]): ContentMeta {
  return { id, version: 1, provenance: "source-grounded", review: "pending", author: "ai-draft", sources, lastVerified: DATE };
}

function inv(sources: string[], entry: Omit<Investigation, "meta">): Investigation {
  return { ...entry, meta: meta(entry.id, sources) };
}

